### Ran Playwright code
```js
await page.evaluate('async () => { await document.fonts.ready; await Promise.all([...document.images].map(img=>img.decode())); const theme=document.documentElement.dataset.theme; if(theme!==\'dark\')throw Error(\'Tema incorreto\'); if(document.documentElement.scrollWidth>innerWidth)throw Error(\'Rolagem horizontal\'); const links=[...document.querySelectorAll(\'.link-list a\')].map(a=>({text:a.textContent.trim(),href:a.href,target:a.target,rel:a.rel})); if(links.length!==4)throw Error(\'Quantidade de links incorreta\'); if(!links.every(a=>a.target===\'_blank\'&&a.rel.includes(\'noopener\')))throw Error(\'Atributos dos links\'); const img=document.querySelector(\'.profile__avatar\'); if(!img.src.includes(\'original\'))throw Error(\'Foto incorreta\'); return {theme,width:innerWidth,horizontalOverflow:false,links,avatar:img.alt,socialLinks:[...document.querySelectorAll(\'.social-links a\')].map(a=>a.href)}; }');
```

